@Mod("phase_two_probe") public class BatchProbe {
 List<String> lines=new ArrayList<>();int count,failures;ServerLevel w;ServerPlayer p;
 public BatchProbe(){NeoForge.EVENT_BUS.addListener(this::start);}
 void check(boolean ok,String label){lines.add((ok?"PASS ":"FAIL ")+label);if(!ok)failures++;count++;}
 void eq(String label,double actual,double expected){check(Math.abs(actual-expected)<.015,label+" actual="+actual+" expected="+expected);}
 Holder<Spell> spell(String id){return SpellRegistry.from(w).get(Identifier.parse(id)).orElseThrow();}
 Holder<MobEffect> effect(String id){return BuiltInRegistries.MOB_EFFECT.get(Identifier.parse(id)).orElseThrow();}
 void equip(List<String> pass,List<String> mods){var owner=(SpellContainerSource.Owner)p;var old=owner.getSpellContainers();owner.setSpellContainers(new SpellContainerSource.Result(old.activeContainer(),List.of(),pass.stream().map(this::spell).toList(),mods.stream().map(this::spell).toList(),List.of()));owner.spellModifierCache().clear();((SpellCaster.Player)p).getCooldownManager().reset(null);}
 void reset(){p.removeAllEffects();p.setAbsorptionAmount(0);p.invulnerableTime=0;p.setItemSlot(EquipmentSlot.MAINHAND,ItemStack.EMPTY);p.setItemSlot(EquipmentSlot.OFFHAND,ItemStack.EMPTY);p.getAttribute(Attributes.MAX_HEALTH).setBaseValue(1000);p.getAttribute(Attributes.ARMOR).setBaseValue(0);p.getAttribute(Attributes.ARMOR_TOUGHNESS).setBaseValue(0);p.setHealth(500);equip(List.of(),List.of());}
 LivingEntity enemy(){var e=EntityTypes.CREEPER.create(w,EntitySpawnReason.COMMAND);e.setPos(0,80,2);e.setNoAi(true);e.setNoGravity(true);e.getAttribute(Attributes.MAX_HEALTH).setBaseValue(1000);e.setHealth(1000);w.addFreshEntity(e);return e;}
 void impacts(LivingEntity target,String id){var h=spell(id);var context=new SpellExecution.ImpactContext().power(new SpellPower.Result(h.value().school,40,0,1));SpellImpacts.performImpacts(w,p,target,target,h,h.value().impacts,context,false,null);}
 void start(ServerStartedEvent event){w=event.getServer().overworld();((net.spell_engine.utils.WorldScheduler)w).schedule(30,()->run(event));}
 void run(ServerStartedEvent event){try{
  event.getServer().setDifficulty(net.minecraft.world.Difficulty.NORMAL,true);w.getGameRules().set(net.minecraft.world.level.gamerules.GameRules.PVP,true,event.getServer());
  p=net.neoforged.neoforge.common.util.FakePlayerFactory.getMinecraft(w);p.connection.markClientLoaded();p.setGameMode(GameType.SURVIVAL);p.setInvulnerable(false);p.getAbilities().invulnerable=false;p.setPos(0,80,0);reset();
  var magic=new net.minecraft.world.damagesource.DamageSource(w.registryAccess().lookupOrThrow(Registries.DAMAGE_TYPE).get(Identifier.parse("spell_power:arcane")).orElseThrow(),enemy());
  check(!magic.is(net.minecraft.tags.DamageTypeTags.BYPASSES_ARMOR),"RPG magic no longer bypasses native armor");
  p.getAttribute(Attributes.ARMOR).setBaseValue(20);float health=p.getHealth();p.hurtServer(w,magic,10);check(p.getHealth()>health-10,"Armor actually mitigates ordinary RPG magic");reset();
  p.addEffect(new MobEffectInstance(MobEffects.RESISTANCE,100));health=p.getHealth();p.hurtServer(w,magic,10);eq("Native Resistance covers magic",health-p.getHealth(),8);reset();
  var defender=EntityTypes.VILLAGER.create(w,EntitySpawnReason.COMMAND);defender.setPos(0,80,0);defender.setNoAi(true);defender.getAttribute(Attributes.MAX_HEALTH).setBaseValue(1000);defender.setHealth(1000);defender.setYRot(0);defender.setYHeadRot(0);defender.setItemInHand(net.minecraft.world.InteractionHand.OFF_HAND,new ItemStack(Items.SHIELD));defender.startUsingItem(net.minecraft.world.InteractionHand.OFF_HAND);w.addFreshEntity(defender);
  var attacker=enemy();attacker.setPos(0,80,4);for(int i=0;i<10;i++)defender.tick();check(defender.getItemBlockingWith()!=null,"Shield active after native raise delay");
  for(boolean isMagic:new boolean[]{false,true}){defender.setHealth(1000);defender.invulnerableTime=0;defender.hurtServer(w,isMagic?new net.minecraft.world.damagesource.DamageSource(magic.typeHolder(),attacker):defender.damageSources().mobAttack(attacker),10);eq("Shield frontal 80% "+isMagic,1000-defender.getHealth(),2);}
  attacker.setPos(0,80,-4);defender.setHealth(1000);defender.invulnerableTime=0;defender.hurtServer(w,new net.minecraft.world.damagesource.DamageSource(magic.typeHolder(),attacker),10);eq("Rear magic not shielded",1000-defender.getHealth(),10);defender.discard();attacker.discard();
  for(int i=1;i<=4;i++){reset();equip(List.of("skill_tree_rpgs:priest_tier_3_passive_1"),List.of());p.setHealth(1000*(.5f-i*.1f)+1);p.tickCount=100;NeoForge.EVENT_BUS.post(new net.neoforged.neoforge.event.tick.EntityTickEvent.Post(p));health=p.getHealth();p.hurtServer(w,magic,10);eq("Pain Suppression magic tier "+i,health-p.getHealth(),10*(1-.06*i));}
  reset();var retentionTarget=enemy();retentionTarget.hurtServer(w,p.damageSources().playerAttack(p),10);eq("Player PvE retention remains 80%",1000-retentionTarget.getHealth(),8);retentionTarget.discard();
  var foe=new net.neoforged.neoforge.common.util.FakePlayer(w,new com.mojang.authlib.GameProfile(UUID.randomUUID(),"PvPProbe")){@Override public boolean canHarmPlayer(net.minecraft.world.entity.player.Player other){return true;}};foe.connection.markClientLoaded();foe.setGameMode(GameType.SURVIVAL);foe.setInvulnerable(false);foe.getAbilities().invulnerable=false;foe.getAttribute(Attributes.MAX_HEALTH).setBaseValue(1000);foe.setHealth(1000);foe.invulnerableTime=0;var attackerPlayer=new net.neoforged.neoforge.common.util.FakePlayer(w,new com.mojang.authlib.GameProfile(UUID.randomUUID(),"PvPAttacker")){@Override public boolean canHarmPlayer(net.minecraft.world.entity.player.Player other){return true;}};attackerPlayer.connection.markClientLoaded();foe.hurtServer(w,p.damageSources().playerAttack(attackerPlayer),10);eq("Player PvP retention remains 35%",1000-foe.getHealth(),3.5);
  var multi=w.registryAccess().lookupOrThrow(Registries.ENCHANTMENT).get(Identifier.parse("combat_roll:multi_roll")).orElseThrow();for(int level:new int[]{1,2,3,10}){p.setItemSlot(EquipmentSlot.HEAD,ItemStack.EMPTY);var helmet=new ItemStack(Items.DIAMOND_HELMET);helmet.enchant(multi,level);p.setItemSlot(EquipmentSlot.HEAD,helmet);double[] contribution={0};net.minecraft.world.item.enchantment.EnchantmentHelper.forEachModifier(helmet,EquipmentSlot.HEAD,(a,m)->{if(a.is(Identifier.parse("combat_roll:count")))contribution[0]+=m.amount();});eq("Multi Roll native equipped modifier level "+level,contribution[0],Math.min(2,level));}p.setItemSlot(EquipmentSlot.HEAD,ItemStack.EMPTY);reset();
  check(com.cozary.nameless_trinkets.pack.PackBalance.removed("fractured_nullstone"),"Fractured Nullstone retired using existing save-safe retirement policy");
  check(!BuiltInRegistries.ITEM.get(Identifier.parse("nameless_trinkets:fractured_nullstone")).orElseThrow().value().getDefaultInstance().is(net.minecraft.tags.ItemTags.create(Identifier.parse("nameless_trinkets:nameless_trinkets_tag"))),"Nullstone absent from acquisition tag");
  var cat=SkillsAPI.getCategory(Utilities.CATEGORY).orElseThrow();cat.unlock(p);cat.setExtraPoints(p,1000);p.getPersistentData().putBoolean("skill_overhaul_v1",true);p.getPersistentData().putBoolean("utilities_v1_migrated",true);p.getPersistentData().putBoolean("defense_v2_refunded",true);
  for(int branch=0;branch<3;branch++){
   cat.resetSkills(p);reset();cat.getSkill("ad8qet8e75ys5sek").orElseThrow().unlock(p);var path=DefenseV2.PATHS.get(branch);
   for(int i=0;i<6;i++)cat.getSkill(path.get(i)).orElseThrow().unlock(p);
   cat.getSkill(path.get(7)).orElseThrow().unlock(p);check(!Utilities.unlocked(p).contains(path.get(7)),"Defense cap cannot skip second branch "+branch);
   cat.getSkill(path.get(6)).orElseThrow().unlock(p);cat.getSkill(path.get(7)).orElseThrow().unlock(p);check(DefenseV2.mastery(p,branch),"Defense mastery selected "+branch);
   eq("Defense armor total "+branch,p.getAttributeValue(Attributes.ARMOR),branch==2?4:2);
   eq("Defense HP total "+branch,p.getMaxHealth(),1000+(branch==0?4:branch==1?6:2));
   double healing=net.puffish.attributesmod.api.DynamicModification.create().withPositive(net.puffish.attributesmod.api.PuffishAttributes.HEALING,p).relativeTo(100);
   eq("Healing received total "+branch,healing,branch==0?4:branch==1?8:0);
   double resist=net.puffish.attributesmod.api.DynamicModification.create().withPositive(net.puffish.attributesmod.api.PuffishAttributes.RESISTANCE,p).relativeTo(100);
   eq("General Resistance total "+branch,resist,branch==0?4:branch==1?2:8);
   eq("Outgoing healing power unchanged "+branch,p.getAttributeValue(BuiltInRegistries.ATTRIBUTE.get(Identifier.parse("spell_power:healing")).orElseThrow()),1);
   cat.getSkill(DefenseV2.PATHS.get((branch+1)%3).get(0)).orElseThrow().unlock(p);check(!Utilities.unlocked(p).contains(DefenseV2.PATHS.get((branch+1)%3).get(0)),"Cross-path selection rejected "+branch);
  }
  cat.resetSkills(p);reset();cat.getSkill("ad8qet8e75ys5sek").orElseThrow().unlock(p);for(var id:DefenseV2.PATHS.get(0))cat.getSkill(id).orElseThrow().unlock(p);p.setHealth(500);p.hurtServer(w,magic,10);check(p.hasEffect(effect("skill_tree_rpgs:aegis_guard")),"Aegis activates after surviving enemy magic");eq("Aegis exact damage-reduction attribute",p.getAttributeValue(BuiltInRegistries.ATTRIBUTE.get(Identifier.parse("spell_engine:damage_taken")).orElseThrow()),85);p.removeEffect(effect("skill_tree_rpgs:aegis_guard"));p.invulnerableTime=0;p.hurtServer(w,magic,10);check(!p.hasEffect(effect("skill_tree_rpgs:aegis_guard")),"Aegis fixed cooldown prevents repeat activation");
  cat.resetSkills(p);reset();cat.getSkill("ad8qet8e75ys5sek").orElseThrow().unlock(p);for(var id:DefenseV2.PATHS.get(1))cat.getSkill(id).orElseThrow().unlock(p);p.setHealth(200);p.hurtServer(w,magic,10);check(p.getPersistentData().getIntOr("defense_v2_heals",0)==5,"Colossus queues five recovery ticks after low-health hit");health=p.getHealth();for(int i=0;i<5;i++){p.getPersistentData().putLong("defense_v2_heal_at",0);NeoForge.EVENT_BUS.post(new net.neoforged.neoforge.event.tick.EntityTickEvent.Post(p));}eq("Colossus recovery uses sampled max HP and healing received",p.getHealth()-health,p.getMaxHealth()*.1*1.08);check(p.getPersistentData().getIntOr("defense_v2_heals",0)==0,"Colossus recovery stops after five ticks");
  cat.resetSkills(p);reset();cat.getSkill("50jkue9gpbpznlfd").orElseThrow().unlock(p);cat.getSkill("3gpel3ejgsuvozax").orElseThrow().unlock(p);cat.getSkill("ad8qet8e75ys5sek").orElseThrow().unlock(p);cat.getSkill(DefenseV2.PATHS.get(0).get(0)).orElseThrow().unlock(p);int points=cat.getPointsTotal(p);int xp=cat.getExperience().orElseThrow().getTotal(p);p.getPersistentData().remove("defense_v2_refunded");DefenseV2.migrate(p);check(Utilities.unlocked(p).contains("3gpel3ejgsuvozax")&&!Utilities.unlocked(p).contains(DefenseV2.PATHS.get(0).get(0)),"Defense migration refunds only Defense rewards");check(cat.getPointsTotal(p)==points&&cat.getExperience().orElseThrow().getTotal(p)==xp,"Defense migration preserves earned points and XP");
  cat.resetSkills(p);reset();cat.getSkill("h8krq290mbf4dwdx").orElseThrow().unlock(p);cat.getSkill("nu1hd3hh115xcpax").orElseThrow().unlock(p);for(var id:Utilities.PATHS.get(0))cat.getSkill(id).orElseThrow().unlock(p);
  p.getFoodData().setFoodLevel(6);p.getFoodData().setSaturation(0);p.tickCount=20;NeoForge.EVENT_BUS.post(new net.neoforged.neoforge.event.tick.EntityTickEvent.Post(p));eq("Fitness fills hunger",p.getFoodData().getFoodLevel(),20);eq("Fitness fills saturation",p.getFoodData().getSaturationLevel(),20);
  for(String id:List.of("rogues:last_stand","rogues:mortal_strike")){var process=new SpellCast.Process(p,spell(id),Items.IRON_SWORD,1,80,0);for(int i=1;i<=5;i++){check(!process.isDue(i*16-1),id+" pulse not early "+i);check(process.isDue(i*16),id+" pulse every 0.8s "+i);process.markDue();}check(!process.isDue(100),id+" exactly five pulses");}
  cat.resetSkills(p);reset();p.getAttribute(Attributes.MAX_HEALTH).setBaseValue(100);p.setHealth(50);
  impacts(p,"rogues:last_stand");eq("First Last Stand pulse adds 20% maximum health",p.getMaxHealth(),120);eq("First Last Stand pulse heals gained health and 20% new maximum",p.getHealth(),94);check(!p.hasEffect(MobEffects.REGENERATION),"Base Last Stand grants no Regeneration");eq("Last Stand cooldown first pulse",net.spell_engine.entity.WarriorUltimates.duration(0,p,spell("rogues:last_stand")),40);
  for(int i=2;i<=5;i++){p.setHealth(20);impacts(p,"rogues:last_stand");eq("Last Stand earned cooldown "+i,net.spell_engine.entity.WarriorUltimates.duration(0,p,spell("rogues:last_stand")),40+5*(i-1));check(p.getHealth()<p.getMaxHealth(),"No special fifth pulse full heal "+i);}
  reset();p.addEffect(new MobEffectInstance(effect("skill_tree_rpgs:vitality"),100,9));eq("Vitality ten armor",p.getAttributeValue(Attributes.ARMOR),10);eq("Vitality twenty HP",p.getMaxHealth(),1020);reset();
  p.addEffect(new MobEffectInstance(effect("skill_tree_rpgs:coated_regeneration_lock"),160));p.addEffect(new MobEffectInstance(MobEffects.REGENERATION,160));health=p.getHealth();MobEffects.REGENERATION.value().applyEffectTick(w,p,0);eq("Regeneration effect blocked",p.getHealth(),health);p.heal(5);eq("Direct healing remains allowed",p.getHealth(),health+5);
  p.getFoodData().setFoodLevel(20);p.getFoodData().setSaturation(20);health=p.getHealth();for(int i=0;i<20;i++)p.getFoodData().tick(p);eq("Natural regeneration blocked",p.getHealth(),health);p.removeEffect(effect("skill_tree_rpgs:coated_regeneration_lock"));MobEffects.REGENERATION.value().applyEffectTick(w,p,0);check(p.getHealth()>health,"Regeneration resumes after lock removed");
  reset();var victim=enemy();victim.getAttribute(Attributes.ARMOR).setBaseValue(20);p.getAttribute(Attributes.ATTACK_DAMAGE).setBaseValue(26);impacts(victim,"skill_tree_rpgs:rogue_tier_1_passive_2");check(victim.getAttributeValue(Attributes.ARMOR)<=17,"Vital Hit armor scaling applies");check(victim.getHealth()<1000,"Vital Hit physical maximum-health proc damages");victim.discard();
  reset();p.addEffect(new MobEffectInstance(effect("rogues:charge"),100));p.addEffect(new MobEffectInstance(effect(net.spell_engine.entity.WarriorTierTwo.ENDURANCE),100));eq("Endurance gives eight total armor",p.getAttributeValue(Attributes.ARMOR),8);reset();p.addEffect(new MobEffectInstance(effect(net.spell_engine.entity.WarriorUltimates.BERSERKER),100));net.spell_engine.entity.WarriorUltimates.fatal(p);eq("Berserker fatal rescue stun lasts eight seconds",p.getEffect(effect("spell_engine:stun")).getDuration(),160);reset();
  for(var entry:Map.of("arcane_explosion",2.6,"arcane_missile",.26,"arcane_beam",.2,"fire_breath",.14,"fire_meteor",1.5,"frost_nova",1.8,"frost_lance",2.).entrySet()){
   var h=spell("wizards:"+entry.getKey());var target=enemy();float multiplier=SpellParameters.channelValueMultiplier(h.value());if(multiplier==0)multiplier=1;var ctx=new SpellExecution.ImpactContext(multiplier,1,null,new SpellPower.Result(h.value().school,40,0,1),SpellTarget.FocusMode.DIRECT,0);SpellImpacts.performImpacts(w,p,target,p,h,h.value().impacts,ctx,false,Spell.Impact.Action.Type.DAMAGE);eq("Restored native mage damage "+entry.getKey(),1000-target.getHealth(),40*entry.getValue()*.8);target.discard();
  }
  Files.writeString(Path.of("phase-two-result.txt"),(failures==0?"PASS ":"FAIL ")+count+" checks; failures="+failures+"\n");
 }catch(Throwable e){e.printStackTrace();try{Files.writeString(Path.of("phase-two-result.txt"),"FAIL "+e);}catch(Exception ignored){}}finally{try{Files.write(Path.of("phase-two-checks.txt"),lines);}catch(Exception ignored){}event.getServer().halt(false);}}
}
